parameters.jsCode:
const urgency = $input.item.json.newUrgency;
const now = new Date();
let slaDeadline;

if (urgency === "Emergency") {
  slaDeadline = new Date(now.getTime() + 15 * 60 * 1000);
} else if (urgency === "Urgent") {
  slaDeadline = new Date(now.getTime() + 4 * 60 * 60 * 1000);
} else {
  slaDeadline = new Date(now.getTime() + 24 * 60 * 60 * 1000);
}

return { ...($input.item.json), slaDeadline: slaDeadline.toISOString() };

